class Session {
  std::unordered_map<Key, std::shared_ptr<Entity>> map_;
public:
  std::shared_ptr<Entity> findOrLoad(const Key& k) {
    auto it = map_.find(k);
    if (it != map_.end()) return it->second;
    auto e = std::make_shared<Entity>(load(k));   // SQL only on miss
    map_.emplace(k, e);
    return e;
  }
};
